/**
 * modules/CoreModule/ziwei-horoscope.js —— 紫微四化 · 流年流月流日 C29【单一真源 · 适配层】
 *
 * 算什么：在 ziwei.js（iztro 适配层，命盘 + 大限 + 流运原始数据）之上，补「四化」这一层——
 *         ① 十天干四化表（禄/权/科/忌 各化何星）
 *         ② 生年四化落宫（读 iztro 星曜自带 mutagen，不自推）
 *         ③ 大限 / 小限 / 流年 / 流月 / 流日 / 流时 六层流运四化与落宫
 *         ④ 流年十二宫映射（本命十二宫 → 流年宫名）
 *         ⑤ 四化落宫断语（性质 × 宫位领域合成）+ 三方四正提示
 *
 * 权威来源（有权威用权威，零臆造）：
 *   · 十天干四化表取**中州派（陆斌兆）**口径，并与内嵌 iztro 2.6.2 逐干反推核对一致（10/10 全等）：
 *       甲 廉贞禄·破军权·武曲科·太阳忌　乙 天机禄·天梁权·紫微科·太阴忌
 *       丙 天同禄·天机权·文昌科·廉贞忌　丁 太阴禄·天同权·天机科·巨门忌
 *       戊 贪狼禄·太阴权·右弼科·天机忌　己 武曲禄·贪狼权·天梁科·文曲忌
 *       庚 太阳禄·武曲权·太阴科·天同忌　辛 巨门禄·太阳权·文曲科·文昌忌
 *       壬 天梁禄·紫微权·左辅科·武曲忌　癸 破军禄·巨门权·太阴科·贪狼忌
 *     📌 流派分歧（如实并列，不合并）：戊干「右弼化科 / 天机化科」、壬干「左辅化科 / 天府化科」两处最常争议；
 *        本内核取中州派（与 iztro 一致），换派须整表替换，不得混用。
 *   · 星曜安放、四化落宫、大限/流年/流月/流日/流时干支与命宫位，**全部由 iztro 计算**（本文件不重算任何星）。
 *   · 四化性质（禄=增益顺遂/权=掌控扩张/科=名声贵助/忌=阻滞亏欠）为斗数通义，各家表述略异而义同。
 *   · 三方四正 = 命宫 · 财帛 · 官禄 · 迁移（斗数定式）。
 *
 * 加载：UMD —— require（注入 ziwei）；浏览器挂 NT.core.ziweiHoroscope。
 * 校验：modules/CoreModule/__tests__/ziweihoroscope.test.js
 *
 * 交叉验证状态（守零臆造，如实标注）：
 *   ✅ 十天干四化表：与 iztro 逐干反推 10/10 全等。
 *   ✅ 六层流运（大限/小限/流年/流月/流日/流时）干支、命宫位、四化四星：iztro 原值直取。
 *   📌 四化落宫断语为「四化性质 × 宫位领域」**合成句**，非古籍逐条原文；原书逐条象义（各家异文多）不硬套，
 *      避免与流派不一致而假报。合成为定性提示，不作绝对断言。
 *   📌 流运十二宫各自干支未出（iztro 只给该层命宫干支），五虎遁推流宫干属另一层推导，未做即不假报。
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) {
    module.exports = factory(require('./ziwei.js'));
  } else {
    root.NT = root.NT || {}; root.NT.core = root.NT.core || {};
    root.NT.core.ziweiHoroscope = factory(root.NT.core && root.NT.core.ziwei);
  }
})(typeof self !== 'undefined' ? self : this, function (ZW) {

  // ===== 十天干四化表（中州派陆斌兆口径；与 iztro 逐干反推一致）=====
  var SIHUA = {
    甲: ['廉贞', '破军', '武曲', '太阳'],
    乙: ['天机', '天梁', '紫微', '太阴'],
    丙: ['天同', '天机', '文昌', '廉贞'],
    丁: ['太阴', '天同', '天机', '巨门'],
    戊: ['贪狼', '太阴', '右弼', '天机'],
    己: ['武曲', '贪狼', '天梁', '文曲'],
    庚: ['太阳', '武曲', '太阴', '天同'],
    辛: ['巨门', '太阳', '文曲', '文昌'],
    壬: ['天梁', '紫微', '左辅', '武曲'],
    癸: ['破军', '巨门', '太阴', '贪狼']
  };
  var HUA = ['禄', '权', '科', '忌'];

  // ===== 十二宫领域（斗数通义）=====
  var GONG_YI = {
    命宫: '本人性格、格局、体貌与整体运势',
    兄弟: '兄弟姐妹、同辈、合伙与母亲',
    夫妻: '配偶、婚姻感情与异性缘',
    子女: '子女、晚辈、桃花与合作成果',
    财帛: '钱财进出、理财与赚钱方式',
    疾厄: '身体健康、疾病与情绪',
    迁移: '外出、驿马、社交与在外际遇',
    仆役: '朋友、部属、人际与竞争',
    交友: '朋友、部属、人际与竞争',
    官禄: '事业、工作、学业与地位',
    田宅: '房产、家庭、储蓄与居住环境',
    福德: '福分、精神享受、兴趣与寿元',
    父母: '父母、长辈、文书与庇荫'
  };
  // ===== 四化性质 =====
  var HUA_YI = {
    禄: { 性: '吉', 义: '增益、顺遂、因缘、财禄', 句: '有增益顺遂之应，宜顺势取之，忌贪多而失守' },
    权: { 性: '吉（带争）', 义: '权力、掌控、扩张、竞争', 句: '有主导扩张之应，能推得动事，亦易起摩擦越界' },
    科: { 性: '吉', 义: '名声、贵人、文书、条理', 句: '有名声贵助之应，宜以名以文取胜，事多能平顺收尾' },
    忌: { 性: '凶', 义: '阻滞、亏欠、纠缠、执着', 句: '有阻滞亏欠之应，宜守成解结，留意纠缠与破耗，不宜强进' }
  };

  var ORD = { 禄: 0, 权: 1, 科: 2, 忌: 3 };

  /** 命宫三方四正（命/财帛/官禄/迁移）的宫位下标 */
  function 三方四正(星表) {
    var want = ['命宫', '财帛', '官禄', '迁移'], out = [];
    want.forEach(function (n) {
      for (var i = 0; i < 星表.length; i++) {
        if (星表[i].宫 === n) { out.push(i); return; }
      }
    });
    return out;
  }

  /** 星曜落在本命哪一宫（主星与辅星都查） */
  function 星落宫(星表, 星) {
    if (!星) return null;
    for (var i = 0; i < 星表.length; i++) {
      if (星表[i].主星.indexOf(星) >= 0 || 星表[i].辅星.indexOf(星) >= 0) return 星表[i];
    }
    return null;
  }

  /** 四化 × 宫位 → 合成断语（如实标注为合成，非古籍逐条） */
  function 合成断语(化, 宫) {
    var y = HUA_YI[化];
    var d = GONG_YI[宫];
    if (!y || !d) return '';
    return '化' + 化 + '入' + 宫 + '：' + d + y.句 + '。';
  }

  /**
   * 四化 + 流运全解。
   * @param inp 出生资料 { y, m, d, h, gender }
   * @param target 目标日期 'YYYY-MM-DD' 或 { y, m, d }
   */
  function analyze(inp, target) {
    if (!ZW || !ZW.chart || !ZW.horoscope) return { err: '紫微四化需 ziwei 内核（iztro）' };
    var c = ZW.chart(inp);
    if (c.err) return c;
    var h = ZW.horoscope(inp, target);
    if (h.err) return h;

    // 生年四化：读 iztro 在星曜上标的 mutagen（主星与辅星并扫），不自推
    var 生年 = [];
    (c.十二宫 || []).forEach(function (p) {
      (p.四化项 || []).forEach(function (x) {
        生年.push({ 化: x.化, 星: x.星, 宫: p.宫, 宫干支: p.干支 });
      });
    });
    生年.sort(function (a, b) { return ORD[a.化] - ORD[b.化]; });

    var 三正 = 三方四正(h.星表);

    // 六层流运四化
    var 层 = h.层.map(function (L) {
      var 项 = HUA.map(function (hn, i) {
        var star = L.四化[i] || null;
        var g = star ? 星落宫(h.星表, star) : null;
        return {
          化: hn, 星: star,
          宫: g ? g.宫 : (star ? '（本命十二宫未见此星）' : '（本层无化）'),
          宫位: g ? g.位 : -1,
          入三方: !!(g && 三正.indexOf(g.位) >= 0),
          断: g ? 合成断语(hn, g.宫) : ''
        };
      });
      return {
        层: L.层, 干支: L.干支, 干: L.干, 支: L.支,
        命宫宫名: L.命宫宫名, 命宫位: L.命宫位, 岁区间: L.岁区间,
        项: 项, 十二宫: L.十二宫
      };
    });

    // 流年十二宫映射（本命宫 → 流年宫名）
    var 流年 = 层.filter(function (x) { return x.层 === '流年'; })[0] || null;
    var 映射 = [];
    if (流年) {
      h.星表.forEach(function (s, i) {
        映射.push({ 位: i, 本命宫: s.宫, 本命干支: s.干支, 流年宫: (流年.十二宫 || [])[i] || '' });
      });
    }

    return {
      生日: h.生日, 目标日: h.目标日, 农历: h.农历,
      命盘: {
        命宫: c.命宫, 身宫: c.身宫, 五行局: c.五行局,
        命主星: c.命主星, 身主星: c.身主星,
        命宫地支: c.命宫地支, 身宫地支: c.身宫地支
      },
      星表: h.星表,
      三方四正: 三正,
      生年: 生年,
      层: 层,
      流年映射: 映射,
      说明: [
        '十天干四化取中州派（陆斌兆）口径，已与内嵌 iztro 2.6.2 逐干反推核对：10 干全等。',
        '流派分歧：戊干「右弼化科／天机化科」、壬干「左辅化科／天府化科」两处最常争议；本内核取中州派，换派须整表替换，不可混用。',
        '四化落宫断语为「四化性质 × 宫位领域」合成句，非古籍逐条原文；合成为定性提示，不作绝对断言。',
        '流运十二宫各自干支未出（iztro 只给该层命宫干支），五虎遁推流宫干属另一层推导，未做即不假报。',
        '星曜安星、四化落宫位置、六层流运干支与命宫位，全部由 iztro 计算，本文件不重算任何星。'
      ]
    };
  }

  /** 只要十天干四化表（不排盘） */
  function sihuaTable(gan) {
    if (gan) {
      var a = SIHUA[gan];
      if (!a) return null;
      return HUA.map(function (h, i) { return { 化: h, 星: a[i] }; });
    }
    var out = {};
    Object.keys(SIHUA).forEach(function (g) {
      out[g] = HUA.map(function (hh, i) { return { 化: hh, 星: SIHUA[g][i] }; });
    });
    return out;
  }

  return {
    analyze: analyze, sihuaTable: sihuaTable,
    合成断语: 合成断语, 星落宫: 星落宫, 三方四正: 三方四正,
    SIHUA: SIHUA, HUA: HUA, GONG_YI: GONG_YI, HUA_YI: HUA_YI
  };
});
